import { Injectable, signal, computed, inject } from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop';
import { PreguntaSeguridad } from '../models/pregunta.model';
import { AsociacionUsuarioPregunta } from '../models/asociacion.model';
import { FiltrosAsociaciones } from '../models/filtros.model';
import { UsuarioSimple } from '../facades/accesos.facade';

@Injectable({ providedIn: 'root' })
export class AccesosState {
  // Signals para estado reactivo
  private preguntasSignal = signal<PreguntaSeguridad[]>([]);
  private asociacionesSignal = signal<AsociacionUsuarioPregunta[]>([]);
  private loadingSignal = signal<boolean>(false);
  private errorSignal = signal<string | null>(null);
  private filtrosAsociacionesSignal = signal<FiltrosAsociaciones>({ id_usuario: null, id_pregunta: null });
  private paginaActualPreguntasSignal = signal<number>(1);
  private paginaActualAsociacionesSignal = signal<number>(1);
  private usuariosSignal = signal<UsuarioSimple[]>([]);
  // Computed signals
  readonly preguntas = this.preguntasSignal.asReadonly();
  readonly usuarios = this.usuariosSignal.asReadonly();
  readonly asociaciones = this.asociacionesSignal.asReadonly();
  readonly loading = this.loadingSignal.asReadonly();
  readonly error = this.errorSignal.asReadonly();
  readonly filtrosAsociaciones = this.filtrosAsociacionesSignal.asReadonly();
  readonly paginaActualPreguntas = this.paginaActualPreguntasSignal.asReadonly();
  readonly paginaActualAsociaciones = this.paginaActualAsociacionesSignal.asReadonly();

  // Computed values
  readonly totalPreguntas = computed(() => this.preguntasSignal().length);
  readonly preguntasActivas = computed(() => this.preguntasSignal().filter(p => p.activo).length);
  readonly totalAsociaciones = computed(() => this.asociacionesSignal().length);
 readonly asociacionesFiltradas = computed(() => {
    const filtros = this.filtrosAsociacionesSignal();
    let items = this.asociacionesSignal();

    console.log('🔍 Filtrando asociaciones:', {
        filtrosUsuario: filtros.id_usuario,
        filtrosUsuarioType: typeof filtros.id_usuario,
        totalItems: items.length
    });

    if (filtros.id_usuario !== null && filtros.id_usuario !== undefined) {
        // ✅ Convertir a número para comparar
        const usuarioId = Number(filtros.id_usuario);
        items = items.filter(a => a.id_usuario === usuarioId);
        console.log('  - Después de filtrar por usuario:', items.length);
    }
    if (filtros.id_pregunta !== null && filtros.id_pregunta !== undefined) {
        const preguntaId = Number(filtros.id_pregunta);
        items = items.filter(a => a.id_pregunta === preguntaId);
        console.log('  - Después de filtrar por pregunta:', items.length);
    }
    return items;
});

  // Actions (métodos para actualizar estado)
  setPreguntas(preguntas: PreguntaSeguridad[]): void {
    this.preguntasSignal.set(preguntas);
  }

  addPregunta(pregunta: PreguntaSeguridad): void {
    this.preguntasSignal.update(prev => [pregunta, ...prev]);
  }

  updatePregunta(id: number, cambios: Partial<PreguntaSeguridad>): void {
    this.preguntasSignal.update(prev =>
      prev.map(p => p.pregunta_id === id ? { ...p, ...cambios } : p)
    );
  }

  removePregunta(id: number): void {
    this.preguntasSignal.update(prev => prev.filter(p => p.pregunta_id !== id));
  }

  setAsociaciones(asociaciones: AsociacionUsuarioPregunta[]): void {
    this.asociacionesSignal.set(asociaciones);
  }

  setUsuarios(usuarios: UsuarioSimple[]): void {
    this.usuariosSignal.set(usuarios);
  }

  addAsociacion(asociacion: AsociacionUsuarioPregunta): void {
    this.asociacionesSignal.update(prev => [asociacion, ...prev]);
  }

  removeAsociacion(usuarioId: number, preguntaId: number): void {
    this.asociacionesSignal.update(prev =>
      prev.filter(a => !(a.id_usuario === usuarioId && a.id_pregunta === preguntaId))
    );
  }

   updateAsociacionValidacion(usuarioId: number, preguntaId: number, validada: boolean): void {
    this.asociacionesSignal.update(prev =>
      prev.map(a =>
        a.id_usuario === usuarioId && a.id_pregunta === preguntaId
          ? { ...a, validada }
          : a
      )
    );
  }

  reset(): void {
    this.preguntasSignal.set([]);
    this.asociacionesSignal.set([]);
    this.usuariosSignal.set([]);
    this.loadingSignal.set(false);
    this.errorSignal.set(null);
    this.filtrosAsociacionesSignal.set({ id_usuario: null, id_pregunta: null });
    this.paginaActualPreguntasSignal.set(1);
    this.paginaActualAsociacionesSignal.set(1);
  }

  setLoading(loading: boolean): void {
    this.loadingSignal.set(loading);
  }

  setError(error: string | null): void {
    this.errorSignal.set(error);
  }

  setFiltrosAsociaciones(filtros: FiltrosAsociaciones): void {
    this.filtrosAsociacionesSignal.set(filtros);
  }

  setPaginaActualPreguntas(pagina: number): void {
    this.paginaActualPreguntasSignal.set(pagina);
  }

  setPaginaActualAsociaciones(pagina: number): void {
    this.paginaActualAsociacionesSignal.set(pagina);
  }

}
