import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { AsociacionUsuarioPregunta, CrearAsociacionDTO } from '../../app/modules/seguridad/pages/accesos/models/asociacion.model';
import { PaginatedResponse } from './pregunta.service';

@Injectable({ providedIn: 'root' })
export class AsociacionService {
  private readonly baseUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  listar(params?: {
    page?: number;
    per_page?: number;
    usuario_id?: number;
    pregunta_id?: number;
  }): Observable<PaginatedResponse<AsociacionUsuarioPregunta>> {
    let httpParams = new HttpParams();
    if (params?.page) httpParams = httpParams.set('page', params.page);
    if (params?.per_page) httpParams = httpParams.set('per_page', params.per_page);
    if (params?.usuario_id) httpParams = httpParams.set('usuario_id', params.usuario_id);
    if (params?.pregunta_id) httpParams = httpParams.set('pregunta_id', params.pregunta_id);

    return this.http.get<PaginatedResponse<AsociacionUsuarioPregunta>>(`${this.baseUrl}/usuarios-preguntas`, { params: httpParams });
  }

  crear(data: CrearAsociacionDTO): Observable<{ success: boolean; message: string; data: any }> {
    return this.http.post<{ success: boolean; message: string; data: any }>(`${this.baseUrl}/usuarios-preguntas`, data);
  }

  eliminar(usuarioId: number, preguntaId: number): Observable<{ success: boolean; message: string }> {
    return this.http.delete<{ success: boolean; message: string }>(`${this.baseUrl}/usuarios/${usuarioId}/preguntas/${preguntaId}`);
  }

  validarRespuesta(data: { usuario_id: number; pregunta_id: number; respuesta: string }): Observable<{ success: boolean; valido: boolean; message: string }> {
    return this.http.post<{ success: boolean; valido: boolean; message: string }>(`${this.baseUrl}/usuarios-preguntas/validar`, data);
  }

validarMasiva(asociaciones: Array<{ usuario_id: number; pregunta_id: number }>): Observable<any> {
    console.log('📡 AsociacionService.validarMasiva:', asociaciones);
    return this.http.post(`${this.baseUrl}/usuarios-preguntas/validar-masiva`, { asociaciones });
}
obtenerRespuesta(usuarioId: number, preguntaId: number): Observable<any> {
    const url = `${this.baseUrl}/usuarios/${usuarioId}/preguntas/${preguntaId}/respuesta`;
    console.log('📡 GET:', url);
    return this.http.get(url);
}

actualizarRespuesta(usuarioId: number, preguntaId: number, respuesta: string): Observable<any> {
    return this.http.put(`${this.baseUrl}/usuarios/${usuarioId}/preguntas/${preguntaId}/respuesta`, { respuesta });
}
obtenerPreguntasPorUsuario(usuarioId: number): Observable<any> {
    return this.http.get(`${this.baseUrl}/usuarios/${usuarioId}/preguntas-asociadas`);
}
}
