  get preguntasDisponiblesValue(): PreguntaSeguridad[] {
    if (!this.asociacionFormData.usuario_id) {
      return this.preguntasActivasListValue;
    }
    const preguntasUsuario = this.state.asociaciones()
      .filter(a => a.id_usuario === this.asociacionFormData.usuario_id)
      .map(a => a.id_pregunta);
    return this.preguntasActivasListValue.filter(p => !preguntasUsuario.includes(p.pregunta_id));
  }

