import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../environments/environment';

export interface ValidacionRespuestaDTO {
  usuario_id: number;
  pregunta_id: number;
  respuesta: string;
}

// ✅ Exportar explícitamente ValidacionResultado
export interface ValidacionResultado {
  success: boolean;
  valido?: boolean;
  message: string;
  requiere_nuevas_preguntas?: boolean;
  nuevas_preguntas?: Array<{ pregunta_id: number; texto: string }>;
  intentos_fallidos?: number;
  bloqueado_hasta?: string;
}

@Injectable({ providedIn: 'root' })
export class ValidacionService {
  private readonly baseUrl = `${environment.apiUrl}`;

  constructor(private http: HttpClient) {}

  /**
   * Validar una respuesta de seguridad específica
   * ENDPOINT REAL DEL BACKEND: POST /api/v1/usuarios-preguntas/validar
   */
  validarRespuestaIndividual(data: ValidacionRespuestaDTO): Observable<ValidacionResultado> {
    return this.http.post<ValidacionResultado>(`${this.baseUrl}/usuarios-preguntas/validar`, data);
  }

  /**
   * Validar múltiples respuestas (flujo de login)
   * ENDPOINT REAL DEL BACKEND: POST /api/v1/auth/validar-preguntas
   */
  validarMultiplesRespuestas(data: {
    usuario_id: number;
    session_id?: string;
    respuestas: Array<{ pregunta_id: number; respuesta: string }>;
    preguntas_usadas?: number[];
  }): Observable<ValidacionResultado> {
    return this.http.post<ValidacionResultado>(`${this.baseUrl}/auth/validar-preguntas`, data);
  }
}
