import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { PreguntaSeguridad, CrearPreguntaDTO, ActualizarPreguntaDTO } from '../../app/modules/seguridad/pages/accesos/models/pregunta.model';

export interface PaginatedResponse<T> {
  success: boolean;
  data: T[];
  meta: {
    total: number;
    per_page: number;
    current_page: number;
    last_page: number;
  };
}

@Injectable({ providedIn: 'root' })
export class PreguntaService {
  private readonly baseUrl = `${environment.apiUrl}/preguntas-seguridad`;

  constructor(private http: HttpClient) {}

  listar(params?: {
    page?: number;
    per_page?: number;
    activo?: boolean;
    search?: string;
  }): Observable<PaginatedResponse<PreguntaSeguridad>> {
    let httpParams = new HttpParams();
    if (params?.page) httpParams = httpParams.set('page', params.page);
    if (params?.per_page) httpParams = httpParams.set('per_page', params.per_page);
    if (params?.activo !== undefined) httpParams = httpParams.set('activo', params.activo);
    if (params?.search) httpParams = httpParams.set('search', params.search);

    return this.http.get<PaginatedResponse<PreguntaSeguridad>>(this.baseUrl, { params: httpParams });
  }

  obtener(id: number): Observable<{ success: boolean; data: PreguntaSeguridad }> {
    return this.http.get<{ success: boolean; data: PreguntaSeguridad }>(`${this.baseUrl}/${id}`);
  }

  crear(data: CrearPreguntaDTO): Observable<{ success: boolean; message: string; data: PreguntaSeguridad }> {
    return this.http.post<{ success: boolean; message: string; data: PreguntaSeguridad }>(this.baseUrl, data);
  }

  actualizar(id: number, data: ActualizarPreguntaDTO): Observable<{ success: boolean; message: string; data: PreguntaSeguridad }> {
    return this.http.put<{ success: boolean; message: string; data: PreguntaSeguridad }>(`${this.baseUrl}/${id}`, data);
  }

  eliminar(id: number): Observable<{ success: boolean; message: string }> {
    return this.http.delete<{ success: boolean; message: string }>(`${this.baseUrl}/${id}`);
  }
}
