import { Injectable } from '@angular/core';
import { PreguntaSeguridad } from '../modules/seguridad/pages/accesos/models/pregunta.model';
import { AsociacionUsuarioPregunta } from '../modules/seguridad/pages/accesos/models/asociacion.model';

export interface ReporteEstadistica {
  label: string;
  value: string | number;
}

export interface ReporteData {
  titulo: string;
  fecha: Date;
  totalRegistros: number;
  estadisticas: ReporteEstadistica[];
  datos: any;
}

@Injectable({ providedIn: 'root' })
export class ReporteService {
  generarReportePreguntas(preguntas: PreguntaSeguridad[], totalPreguntas: number, preguntasActivas: number): ReporteData {
    return {
      titulo: 'Reporte de Preguntas de Seguridad',
      fecha: new Date(),
      totalRegistros: preguntas.length,
      estadisticas: [
        { label: 'Total Preguntas', value: totalPreguntas },
        { label: 'Preguntas Activas', value: preguntasActivas },
        { label: 'Preguntas Inactivas', value: totalPreguntas - preguntasActivas }
      ],
      datos: preguntas.map(p => ({
        id: p.pregunta_id,
        pregunta: p.texto,
        estado: p.activo ? 'Activa' : 'Inactiva',
        usuarios: p.usuarios_asociados || 0,
        fecha_creacion: p.fecha_creacion
      }))
    };
  }

  generarReporteAsociaciones(asociaciones: AsociacionUsuarioPregunta[], totalAsociaciones: number): ReporteData {
    const validadas = asociaciones.filter(a => a.validada).length;
    return {
      titulo: 'Reporte de Asociaciones Usuario-Pregunta',
      fecha: new Date(),
      totalRegistros: asociaciones.length,
      estadisticas: [
        { label: 'Total Asociaciones', value: totalAsociaciones },
        { label: 'Respuestas Validadas', value: validadas },
        { label: 'Tasa de Validación', value: `${((validadas / totalAsociaciones) * 100).toFixed(1)}%` }
      ],
      datos: asociaciones.map(a => ({
        usuario: a.usuario_nombre,
        pregunta: a.pregunta_texto,
        validada: a.validada ? 'Sí' : 'No',
        fecha_asociacion: a.fecha_asociacion
      }))
    };
  }

  exportarPDF(reporte: ReporteData): void {
    console.log('Exportando PDF:', reporte.titulo);
    // Implementación real con librería PDF
  }

  exportarExcel(reporte: ReporteData): void {
    console.log('Exportando Excel:', reporte.titulo);
    // Implementación real con librería Excel
  }
}
