import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, map, tap } from 'rxjs';
import { PreguntaService } from '../../../../../services/pregunta.service';
import { AsociacionService } from '../../../../../services/asociacion.service';
import { ValidacionService, ValidacionRespuestaDTO, ValidacionResultado } from '../../../../../services/validacion.service';
import { ReporteService, ReporteData } from '../../../../../services/reporte.service';
import { PreguntaSeguridad, CrearPreguntaDTO, ActualizarPreguntaDTO } from '../models/pregunta.model';
import { AsociacionUsuarioPregunta, CrearAsociacionDTO } from '../models/asociacion.model';
import { UsuarioService } from '../../../../../services/usuario.service';
import { AccesosState } from '../store/accesos.state'; // ✅ IMPORTAR STATE

export interface UsuarioSimple {
  id_usuario: number;
  nombre_usuario: string;
  nombres: string;
  apellidos: string;
  email: string;
}

@Injectable({ providedIn: 'root' })
export class AccesosFacadeService {
  private preguntasSubject = new BehaviorSubject<PreguntaSeguridad[]>([]);
  private asociacionesSubject = new BehaviorSubject<AsociacionUsuarioPregunta[]>([]);
  private loadingSubject = new BehaviorSubject<boolean>(false);
  private errorSubject = new BehaviorSubject<string | null>(null);
  private usuariosSubject = new BehaviorSubject<UsuarioSimple[]>([]);

  public preguntas$ = this.preguntasSubject.asObservable();
  public asociaciones$ = this.asociacionesSubject.asObservable();
  public loading$ = this.loadingSubject.asObservable();
  public error$ = this.errorSubject.asObservable();
  public usuarios$ = this.usuariosSubject.asObservable();

  constructor(
    private preguntaService: PreguntaService,
    private asociacionService: AsociacionService,
    private validacionService: ValidacionService,
    private usuarioService: UsuarioService,
    private reporteService: ReporteService,
    private state: AccesosState  // ✅ INYECTAR STATE
  ) {}

  // ========== Usuarios ==========
  cargarUsuarios(): void {
    console.log('📡 Facade: cargando usuarios...');
    this.usuarioService.listar().subscribe({
      next: (response) => {
        console.log('✅ Usuarios recibidos:', response.data?.length || 0);
        const usuarios = (response.data || []).map((u: any) => ({
          id_usuario: u.usuario_id,
          nombre_usuario: u.nombre_usuario,
          nombres: u.personal?.persona?.nombres || u.nombre_usuario,
          apellidos: u.personal?.persona?.apellidos || '',
          email: u.email
        }));

        // ✅ ACTUALIZAR STATE
        this.state.setUsuarios(usuarios);
        this.usuariosSubject.next(usuarios);

        console.log('👥 State actualizado con usuarios:', this.state.usuarios().length);
      },
      error: (error) => {
        console.error('❌ Error cargando usuarios:', error);
      }
    });
  }

  get usuarios(): UsuarioSimple[] {
    return this.usuariosSubject.value;
  }

  // ========== Preguntas ==========
  cargarPreguntas(params?: any): void {
    console.log('📡 Facade: cargando preguntas con params:', params);
    this.loadingSubject.next(true);
    this.preguntaService.listar(params).subscribe({
      next: (response) => {
        const preguntas = response.data || [];
        console.log('✅ Preguntas recibidas:', preguntas.length);

        // ✅ ACTUALIZAR STATE
        this.state.setPreguntas(preguntas);
        this.preguntasSubject.next(preguntas);

        console.log('📝 State actualizado con preguntas:', this.state.preguntas().length);
        this.loadingSubject.next(false);
      },
      error: (error) => {
        console.error('❌ Error cargando preguntas:', error);
        this.loadingSubject.next(false);
        this.errorSubject.next(error.message);
      }
    });
  }

  crearPregunta(data: CrearPreguntaDTO): Observable<PreguntaSeguridad> {
    return this.preguntaService.crear(data).pipe(
      tap((response) => {
        if (response.success) {
          const preguntasActuales = this.state.preguntas();
          this.state.setPreguntas([response.data, ...preguntasActuales]);
          this.preguntasSubject.next([response.data, ...preguntasActuales]);
        }
      }),
      map(response => response.data)
    );
  }

  actualizarPregunta(id: number, data: ActualizarPreguntaDTO): Observable<PreguntaSeguridad> {
    return this.preguntaService.actualizar(id, data).pipe(
      tap((response) => {
        if (response.success) {
          const preguntasActuales = this.state.preguntas();
          const index = preguntasActuales.findIndex(p => p.pregunta_id === id);
          if (index !== -1) {
            const nuevasPreguntas = [...preguntasActuales];
            nuevasPreguntas[index] = response.data;
            this.state.setPreguntas(nuevasPreguntas);
            this.preguntasSubject.next(nuevasPreguntas);
          }
        }
      }),
      map(response => response.data)
    );
  }

  eliminarPregunta(id: number): Observable<void> {
    return this.preguntaService.eliminar(id).pipe(
      tap(() => {
        const preguntasActuales = this.state.preguntas();
        this.state.setPreguntas(preguntasActuales.filter(p => p.pregunta_id !== id));
        this.preguntasSubject.next(preguntasActuales.filter(p => p.pregunta_id !== id));
      }),
      map(() => void 0)
    );
  }

  // ========== Asociaciones ==========
  cargarAsociaciones(params?: { page?: number; per_page?: number; usuario_id?: number; pregunta_id?: number }): void {
    this.loadingSubject.next(true);
    this.asociacionService.listar(params).subscribe({
      next: (response) => {
        const asociaciones = response.data || [];
        console.log('✅ Asociaciones recibidas:', asociaciones.length);

        // ✅ ACTUALIZAR STATE
        this.state.setAsociaciones(asociaciones);
        this.asociacionesSubject.next(asociaciones);

        this.loadingSubject.next(false);
        this.errorSubject.next(null);
      },
      error: (error) => {
        this.loadingSubject.next(false);
        this.errorSubject.next(error.message || 'Error al cargar asociaciones');
      }
    });
  }

  crearAsociacion(data: CrearAsociacionDTO): Observable<AsociacionUsuarioPregunta> {
    return this.asociacionService.crear(data).pipe(
      tap((response) => {
        if (response.success) {
          this.cargarAsociaciones();
        }
      }),
      map(() => {
        return {
          id_usuario: data.usuario_id,
          id_pregunta: data.pregunta_id,
          respuesta: '🔒 Encriptada',
          validada: false,
          fecha_asociacion: new Date().toISOString(),
          usuario_nombre: '',
          usuario_email: '',
          pregunta_texto: ''
        };
      })
    );
  }

  eliminarAsociacion(usuarioId: number, preguntaId: number): Observable<void> {
    return this.asociacionService.eliminar(usuarioId, preguntaId).pipe(
      tap(() => {
        const asociacionesActuales = this.state.asociaciones();
        this.state.setAsociaciones(
          asociacionesActuales.filter(a => a.id_usuario !== usuarioId || a.id_pregunta !== preguntaId)
        );
        this.asociacionesSubject.next(
          asociacionesActuales.filter(a => a.id_usuario !== usuarioId || a.id_pregunta !== preguntaId)
        );
      }),
      map(() => void 0)
    );
  }

  // ========== Validación ==========
  validarRespuestaIndividual(usuarioId: number, preguntaId: number, respuesta: string): Observable<ValidacionResultado> {
    return this.validacionService.validarRespuestaIndividual({
      usuario_id: usuarioId,
      pregunta_id: preguntaId,
      respuesta
    });
  }

  validarMultiplesRespuestas(
    usuarioId: number,
    respuestas: Array<{ pregunta_id: number; respuesta: string }>,
    sessionId?: string,
    preguntasUsadas?: number[]
  ): Observable<ValidacionResultado> {
    return this.validacionService.validarMultiplesRespuestas({
      usuario_id: usuarioId,
      session_id: sessionId,
      respuestas,
      preguntas_usadas: preguntasUsadas
    });
  }

  // ========== Reportes ==========
  generarReportePreguntas(preguntas: PreguntaSeguridad[], total: number, activas: number): ReporteData {
    return this.reporteService.generarReportePreguntas(preguntas, total, activas);
  }

  generarReporteAsociaciones(asociaciones: AsociacionUsuarioPregunta[], total: number): ReporteData {
    return this.reporteService.generarReporteAsociaciones(asociaciones, total);
  }

  exportarReportePDF(reporte: ReporteData): void {
    this.reporteService.exportarPDF(reporte);
  }

  exportarReporteExcel(reporte: ReporteData): void {
    this.reporteService.exportarExcel(reporte);
  }
validarMasiva(asociaciones: Array<{ usuario_id: number; pregunta_id: number }>): Observable<any> {
    console.log('📡 Facade.validarMasiva:', asociaciones);
    return this.asociacionService.validarMasiva(asociaciones);
}

actualizarRespuesta(usuarioId: number, preguntaId: number, respuesta: string): Observable<any> {
    return this.asociacionService.actualizarRespuesta(usuarioId, preguntaId, respuesta).pipe(
        tap(() => {
            // Recargar asociaciones para actualizar el estado
            this.cargarAsociaciones();
        })
    );
}
obtenerRespuesta(usuarioId: number, preguntaId: number): Observable<any> {
    console.log('📡 Facade.obtenerRespuesta:', { usuarioId, preguntaId });
    return this.asociacionService.obtenerRespuesta(usuarioId, preguntaId);
}

obtenerPreguntasPorUsuario(usuarioId: number): Observable<any> {
    console.log('📡 Facade.obtenerPreguntasPorUsuario:', usuarioId);
    return this.asociacionService.obtenerPreguntasPorUsuario(usuarioId);
}
}
